<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';exigir_roles(['Administrador del sistema']);$titulo='Usuarios';require '../../includes/header.php';$rows=$pdo->query("SELECT u.nombre_completo,u.usuario,r.nombre_rol,u.activo,u.ultimo_acceso FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol ORDER BY u.id_usuario")->fetchAll();?><h1>Usuarios</h1><div class="panel tabla-wrap"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Activo</th><th>Último acceso</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['nombre_completo']) ?></td><td><?= h($r['usuario']) ?></td><td><?= h($r['nombre_rol']) ?></td><td><?= h($r['activo']) ?></td><td><?= h($r['ultimo_acceso']) ?></td></tr><?php endforeach;?></tbody></table></div><?php require '../../includes/footer.php';?>